+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #eee;
+}
+
+.thread-root-message {
+    padding: 14px 16px;
+    border-bottom: 1px solid #e8e8e8;
+    background: #fff;
+    flex-shrink: 0;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+.thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
+

